-- RecoverAI schema for Supabase PostgreSQL.
-- GENERATED by backend/scripts/gen_migration.py from app/models.py — do not edit by hand.
--
-- Security model
--   * The browser never talks to these tables. All access goes through the RecoverAI API, which connects with the
--     database owner role and scopes every query to the authenticated merchant (tenant isolation tested in
--     tests/test_platform.py::test_merchant_cannot_see_other_merchants_data).
--   * Row Level Security is ENABLED on every table with NO policies for the `anon` and `authenticated` roles, so the
--     Supabase public/anon key cannot read or write any financial data even if it leaks.
--   * If you later expose tables to Supabase Auth users directly, add per-tenant policies like the commented example.
--   * Money is integer minor units (cents). No raw card data is ever stored.

BEGIN;
CREATE TABLE merchants (
	id VARCHAR(32) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	website VARCHAR(300), 
	industry VARCHAR(100), 
	business_type VARCHAR(60), 
	timezone VARCHAR(64) NOT NULL, 
	default_currency VARCHAR(3) NOT NULL, 
	is_demo BOOLEAN NOT NULL, 
	onboarding_complete BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE ai_usage (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32), 
	provider VARCHAR(20) NOT NULL, 
	model VARCHAR(80) NOT NULL, 
	purpose VARCHAR(40) NOT NULL, 
	success BOOLEAN NOT NULL, 
	latency_ms INTEGER NOT NULL, 
	input_tokens INTEGER, 
	output_tokens INTEGER, 
	error VARCHAR(300), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
);
CREATE INDEX ix_ai_usage_created_at ON ai_usage (created_at);
CREATE INDEX ix_ai_usage_merchant_id ON ai_usage (merchant_id);
CREATE TABLE audit_logs (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32), 
	actor_type VARCHAR(20) NOT NULL, 
	actor_id VARCHAR(64), 
	action VARCHAR(80) NOT NULL, 
	entity_type VARCHAR(40), 
	entity_id VARCHAR(64), 
	summary TEXT NOT NULL, 
	detail JSON, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
);
CREATE INDEX ix_audit_logs_created_at ON audit_logs (created_at);
CREATE INDEX ix_audit_logs_merchant_id ON audit_logs (merchant_id);
CREATE TABLE customers (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	email VARCHAR(320) NOT NULL, 
	country VARCHAR(2), 
	phone VARCHAR(32), 
	marketing_consent BOOLEAN NOT NULL, 
	recovery_contact_consent BOOLEAN NOT NULL, 
	is_demo BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_customer_email UNIQUE (merchant_id, email), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
);
CREATE INDEX ix_customers_merchant_id ON customers (merchant_id);
CREATE TABLE integration_credentials (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	provider VARCHAR(30) NOT NULL, 
	encrypted_payload TEXT NOT NULL, 
	masked JSON NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	last_tested_at TIMESTAMP WITH TIME ZONE, 
	last_error TEXT, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_cred_provider UNIQUE (merchant_id, provider), 
	CONSTRAINT ck_cred_provider CHECK (provider IN ('paypal_sandbox', 'paypal_live', 'anthropic', 'openai', 'gemini', 'resend', 'twilio')), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
);
CREATE INDEX ix_integration_credentials_merchant_id ON integration_credentials (merchant_id);
CREATE TABLE merchant_analytics (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	day VARCHAR(10) NOT NULL, 
	attempts INTEGER NOT NULL, 
	completed INTEGER NOT NULL, 
	failed INTEGER NOT NULL, 
	completed_minor INTEGER NOT NULL, 
	recovered_minor INTEGER NOT NULL, 
	computed_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_analytics_day UNIQUE (merchant_id, day), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
);
CREATE INDEX ix_merchant_analytics_merchant_id ON merchant_analytics (merchant_id);
CREATE TABLE merchant_settings (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	recovery_mode VARCHAR(20) NOT NULL, 
	reminder_intervals_minutes JSON NOT NULL, 
	max_reminders_per_case INTEGER NOT NULL, 
	min_minutes_between_messages INTEGER NOT NULL, 
	abandonment_threshold_minutes INTEGER NOT NULL, 
	pending_alert_after_minutes INTEGER NOT NULL, 
	default_tone VARCHAR(20) NOT NULL, 
	brand_name VARCHAR(200), 
	support_email VARCHAR(320), 
	max_retry_attempts INTEGER NOT NULL, 
	retry_cooldown_minutes INTEGER NOT NULL, 
	max_auto_amount_minor INTEGER NOT NULL, 
	permitted_auto_actions JSON NOT NULL, 
	escalate_after_hours INTEGER NOT NULL, 
	quiet_hours_start INTEGER, 
	quiet_hours_end INTEGER, 
	channels JSON NOT NULL, 
	notify_on JSON NOT NULL, 
	paypal_environment VARCHAR(10) NOT NULL, 
	ai_provider VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_settings_mode CHECK (recovery_mode IN ('AUTOMATIC', 'APPROVAL', 'MANUAL')), 
	UNIQUE (merchant_id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
);
CREATE TABLE notifications (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	kind VARCHAR(30) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	body TEXT NOT NULL, 
	link VARCHAR(200), 
	read BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
);
CREATE INDEX ix_notifications_created_at ON notifications (created_at);
CREATE INDEX ix_notifications_merchant_id ON notifications (merchant_id);
CREATE TABLE paypal_connections (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	environment VARCHAR(10) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	last_success_at TIMESTAMP WITH TIME ZONE, 
	last_error TEXT, 
	last_webhook_at TIMESTAMP WITH TIME ZONE, 
	webhook_id_configured BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (merchant_id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
);
CREATE TABLE products (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	sku VARCHAR(64), 
	price_minor INTEGER NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
);
CREATE INDEX ix_products_merchant_id ON products (merchant_id);
CREATE TABLE revenue_predictions (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	scenario VARCHAR(60) NOT NULL, 
	inputs JSON NOT NULL, 
	at_risk_minor INTEGER NOT NULL, 
	expected_minor INTEGER NOT NULL, 
	low_minor INTEGER NOT NULL, 
	high_minor INTEGER NOT NULL, 
	assumptions JSON NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
);
CREATE INDEX ix_revenue_predictions_merchant_id ON revenue_predictions (merchant_id);
CREATE TABLE users (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	email VARCHAR(320) NOT NULL, 
	full_name VARCHAR(200) NOT NULL, 
	password_hash VARCHAR(200) NOT NULL, 
	role VARCHAR(20) NOT NULL, 
	email_verified BOOLEAN NOT NULL, 
	token_version INTEGER NOT NULL, 
	last_login_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_users_role CHECK (role IN ('owner', 'admin', 'analyst')), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE, 
	UNIQUE (email)
);
CREATE INDEX ix_users_merchant_id ON users (merchant_id);
CREATE TABLE webhook_events (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32), 
	paypal_event_id VARCHAR(80) NOT NULL, 
	event_type VARCHAR(80) NOT NULL, 
	resource_id VARCHAR(80), 
	verification_status VARCHAR(20) NOT NULL, 
	processing_status VARCHAR(20) NOT NULL, 
	processing_error TEXT, 
	is_simulated BOOLEAN NOT NULL, 
	payload JSON NOT NULL, 
	received_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	processed_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_webhook_event_id UNIQUE (paypal_event_id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE SET NULL
);
CREATE INDEX ix_webhook_events_received_at ON webhook_events (received_at);
CREATE INDEX ix_webhook_events_merchant_id ON webhook_events (merchant_id);
CREATE TABLE auth_tokens (
	id VARCHAR(32) NOT NULL, 
	user_id VARCHAR(32) NOT NULL, 
	kind VARCHAR(20) NOT NULL, 
	token_hash VARCHAR(64) NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	used_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_auth_token UNIQUE (token_hash), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE INDEX ix_auth_tokens_user_id ON auth_tokens (user_id);
CREATE TABLE orders (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	customer_id VARCHAR(32) NOT NULL, 
	product_id VARCHAR(32), 
	order_number VARCHAR(40) NOT NULL, 
	description VARCHAR(300) NOT NULL, 
	amount_minor INTEGER NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	data_source VARCHAR(20) NOT NULL, 
	paid_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_orders_status CHECK (status IN ('OPEN', 'PAID', 'CANCELLED', 'REFUNDED')), 
	CONSTRAINT ck_orders_amount CHECK (amount_minor > 0), 
	CONSTRAINT uq_order_number UNIQUE (merchant_id, order_number), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE, 
	FOREIGN KEY(customer_id) REFERENCES customers (id), 
	FOREIGN KEY(product_id) REFERENCES products (id)
);
CREATE INDEX ix_orders_merchant_status ON orders (merchant_id, status);
CREATE INDEX ix_orders_customer_id ON orders (customer_id);
CREATE INDEX ix_orders_merchant_id ON orders (merchant_id);
CREATE TABLE checkout_sessions (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	order_id VARCHAR(32) NOT NULL, 
	customer_id VARCHAR(32) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	last_activity_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	paypal_order_created BOOLEAN NOT NULL, 
	paypal_order_approved BOOLEAN NOT NULL, 
	paypal_order_captured BOOLEAN NOT NULL, 
	abandoned_at TIMESTAMP WITH TIME ZONE, 
	data_source VARCHAR(20) NOT NULL, 
	recovery_token VARCHAR(64), 
	recovery_token_expires_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_sessions_status CHECK (status IN ('ACTIVE', 'ABANDONED', 'CONVERTED', 'EXPIRED')), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE, 
	FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE CASCADE, 
	FOREIGN KEY(customer_id) REFERENCES customers (id), 
	UNIQUE (recovery_token)
);
CREATE INDEX ix_sessions_merchant_status ON checkout_sessions (merchant_id, status);
CREATE INDEX ix_checkout_sessions_merchant_id ON checkout_sessions (merchant_id);
CREATE INDEX ix_checkout_sessions_order_id ON checkout_sessions (order_id);
CREATE TABLE payments (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	order_id VARCHAR(32) NOT NULL, 
	customer_id VARCHAR(32) NOT NULL, 
	checkout_session_id VARCHAR(32), 
	reference VARCHAR(40) NOT NULL, 
	amount_minor INTEGER NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	payment_method VARCHAR(40) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	data_source VARCHAR(20) NOT NULL, 
	paypal_order_id VARCHAR(64), 
	paypal_capture_id VARCHAR(64), 
	paypal_request_id VARCHAR(64), 
	status_verified_by VARCHAR(40), 
	failure_category VARCHAR(40), 
	paypal_issue VARCHAR(80), 
	paypal_debug_id VARCHAR(80), 
	raw_response JSON, 
	risk_level VARCHAR(10), 
	recovery_probability FLOAT, 
	recommended_action VARCHAR(60), 
	is_recovery_attempt BOOLEAN NOT NULL, 
	recovery_case_id VARCHAR(32), 
	reconcile_required BOOLEAN NOT NULL, 
	refunded_minor INTEGER NOT NULL, 
	completed_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_payments_status CHECK (status IN ('CREATED', 'APPROVED', 'AUTHORIZED', 'PENDING', 'COMPLETED', 'DECLINED', 'FAILED', 'CANCELLED', 'EXPIRED', 'PARTIALLY_REFUNDED', 'REFUNDED', 'VOIDED')), 
	CONSTRAINT ck_payments_source CHECK (data_source IN ('PAYPAL_SANDBOX', 'PAYPAL_LIVE', 'DEMO_SIMULATED')), 
	CONSTRAINT ck_payments_amount CHECK (amount_minor > 0), 
	CONSTRAINT uq_payments_paypal_order UNIQUE (paypal_order_id), 
	CONSTRAINT uq_payments_paypal_capture UNIQUE (paypal_capture_id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE, 
	FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE CASCADE, 
	FOREIGN KEY(customer_id) REFERENCES customers (id), 
	FOREIGN KEY(checkout_session_id) REFERENCES checkout_sessions (id)
);
CREATE INDEX ix_payments_customer_id ON payments (customer_id);
CREATE INDEX ix_payments_merchant_id ON payments (merchant_id);
CREATE INDEX ix_payments_order_id ON payments (order_id);
CREATE INDEX ix_payments_merchant_status ON payments (merchant_id, status);
CREATE INDEX ix_payments_merchant_created ON payments (merchant_id, created_at);
CREATE INDEX ix_payments_reference ON payments (reference);
CREATE TABLE payment_events (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	payment_id VARCHAR(32) NOT NULL, 
	event_type VARCHAR(60) NOT NULL, 
	from_status VARCHAR(20), 
	to_status VARCHAR(20), 
	source VARCHAR(30) NOT NULL, 
	detail JSON, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE, 
	FOREIGN KEY(payment_id) REFERENCES payments (id) ON DELETE CASCADE
);
CREATE INDEX ix_payment_events_created_at ON payment_events (created_at);
CREATE INDEX ix_payment_events_merchant_id ON payment_events (merchant_id);
CREATE INDEX ix_payment_events_payment_id ON payment_events (payment_id);
CREATE TABLE recovery_cases (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	order_id VARCHAR(32) NOT NULL, 
	customer_id VARCHAR(32) NOT NULL, 
	payment_id VARCHAR(32), 
	checkout_session_id VARCHAR(32), 
	case_type VARCHAR(30) NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	failure_category VARCHAR(40), 
	amount_minor INTEGER NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	recovery_probability FLOAT, 
	priority_score FLOAT, 
	priority_reason TEXT, 
	reminders_sent INTEGER NOT NULL, 
	last_contacted_at TIMESTAMP WITH TIME ZONE, 
	recovered_payment_id VARCHAR(32), 
	recovered_amount_minor INTEGER NOT NULL, 
	recovered_at TIMESTAMP WITH TIME ZONE, 
	closed_at TIMESTAMP WITH TIME ZONE, 
	escalated_at TIMESTAMP WITH TIME ZONE, 
	data_source VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_cases_status CHECK (status IN ('OPEN', 'AWAITING_APPROVAL', 'IN_PROGRESS', 'RECOVERED', 'CLOSED_ALREADY_PAID', 'CLOSED_UNRECOVERED')), 
	CONSTRAINT ck_cases_type CHECK (case_type IN ('FAILED_PAYMENT', 'ABANDONED_CHECKOUT', 'PENDING_PAYMENT', 'APPROVAL_INCOMPLETE')), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE, 
	FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE CASCADE, 
	FOREIGN KEY(customer_id) REFERENCES customers (id), 
	FOREIGN KEY(payment_id) REFERENCES payments (id), 
	FOREIGN KEY(checkout_session_id) REFERENCES checkout_sessions (id)
);
CREATE INDEX ix_cases_merchant_status ON recovery_cases (merchant_id, status);
CREATE INDEX ix_recovery_cases_merchant_id ON recovery_cases (merchant_id);
CREATE INDEX ix_recovery_cases_order_id ON recovery_cases (order_id);
CREATE TABLE agent_runs (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	case_id VARCHAR(32), 
	payment_id VARCHAR(32), 
	trigger VARCHAR(200) NOT NULL, 
	steps JSON NOT NULL, 
	guardrails JSON NOT NULL, 
	rail JSON, 
	outcome VARCHAR(40) NOT NULL, 
	summary TEXT NOT NULL, 
	data_source VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE, 
	FOREIGN KEY(case_id) REFERENCES recovery_cases (id) ON DELETE CASCADE, 
	FOREIGN KEY(payment_id) REFERENCES payments (id) ON DELETE SET NULL
);
CREATE INDEX ix_agent_runs_created_at ON agent_runs (created_at);
CREATE INDEX ix_agent_runs_merchant_id ON agent_runs (merchant_id);
CREATE INDEX ix_agent_runs_case_id ON agent_runs (case_id);
CREATE TABLE ai_analyses (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	payment_id VARCHAR(32), 
	case_id VARCHAR(32), 
	failure_category VARCHAR(40) NOT NULL, 
	classification_basis TEXT NOT NULL, 
	explanation TEXT NOT NULL, 
	root_cause TEXT NOT NULL, 
	severity INTEGER NOT NULL, 
	recovery_probability FLOAT NOT NULL, 
	probability_factors JSON NOT NULL, 
	recommendation JSON NOT NULL, 
	customer_action_required BOOLEAN NOT NULL, 
	merchant_action_required BOOLEAN NOT NULL, 
	generated_by VARCHAR(20) NOT NULL, 
	model VARCHAR(60), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE, 
	FOREIGN KEY(payment_id) REFERENCES payments (id) ON DELETE CASCADE, 
	FOREIGN KEY(case_id) REFERENCES recovery_cases (id) ON DELETE CASCADE
);
CREATE INDEX ix_ai_analyses_payment_id ON ai_analyses (payment_id);
CREATE INDEX ix_ai_analyses_merchant_id ON ai_analyses (merchant_id);
CREATE TABLE communication_logs (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	case_id VARCHAR(32), 
	customer_id VARCHAR(32) NOT NULL, 
	channel VARCHAR(20) NOT NULL, 
	tone VARCHAR(20) NOT NULL, 
	subject VARCHAR(300) NOT NULL, 
	body TEXT NOT NULL, 
	recovery_link VARCHAR(500), 
	delivery_status VARCHAR(20) NOT NULL, 
	provider VARCHAR(30), 
	provider_message_id VARCHAR(120), 
	error TEXT, 
	generated_by VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	sent_at TIMESTAMP WITH TIME ZONE, 
	delivered_at TIMESTAMP WITH TIME ZONE, 
	clicked_at TIMESTAMP WITH TIME ZONE, 
	to_address VARCHAR(320), 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE, 
	FOREIGN KEY(case_id) REFERENCES recovery_cases (id) ON DELETE CASCADE, 
	FOREIGN KEY(customer_id) REFERENCES customers (id)
);
CREATE INDEX ix_communication_logs_case_id ON communication_logs (case_id);
CREATE INDEX ix_communication_logs_created_at ON communication_logs (created_at);
CREATE INDEX ix_communication_logs_merchant_id ON communication_logs (merchant_id);
CREATE TABLE paypal_invoices (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	case_id VARCHAR(32) NOT NULL, 
	order_id VARCHAR(32) NOT NULL, 
	paypal_invoice_id VARCHAR(64) NOT NULL, 
	invoice_number VARCHAR(64) NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	payer_view_url VARCHAR(500), 
	amount_minor INTEGER NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	paid_payment_id VARCHAR(32), 
	raw JSON, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_paypal_invoice_id UNIQUE (paypal_invoice_id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE, 
	FOREIGN KEY(case_id) REFERENCES recovery_cases (id) ON DELETE CASCADE, 
	FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE CASCADE
);
CREATE INDEX ix_paypal_invoices_case_id ON paypal_invoices (case_id);
CREATE INDEX ix_paypal_invoices_merchant_id ON paypal_invoices (merchant_id);
CREATE TABLE recovery_actions (
	id VARCHAR(32) NOT NULL, 
	merchant_id VARCHAR(32) NOT NULL, 
	case_id VARCHAR(32) NOT NULL, 
	action_type VARCHAR(40) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	requires_approval BOOLEAN NOT NULL, 
	idempotency_key VARCHAR(120) NOT NULL, 
	reason TEXT, 
	payload JSON, 
	scheduled_for TIMESTAMP WITH TIME ZONE, 
	executed_at TIMESTAMP WITH TIME ZONE, 
	approved_by VARCHAR(32), 
	result JSON, 
	blocked_reason TEXT, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_actions_status CHECK (status IN ('PROPOSED', 'SCHEDULED', 'APPROVED', 'EXECUTED', 'REJECTED', 'BLOCKED', 'SKIPPED', 'CANCELLED')), 
	CONSTRAINT uq_action_idem UNIQUE (case_id, idempotency_key), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id) ON DELETE CASCADE, 
	FOREIGN KEY(case_id) REFERENCES recovery_cases (id) ON DELETE CASCADE
);
CREATE INDEX ix_recovery_actions_case_id ON recovery_actions (case_id);
CREATE INDEX ix_recovery_actions_merchant_id ON recovery_actions (merchant_id);

-- Row Level Security: deny-by-default for Supabase client roles
