REVOKE ALL ON integration_credentials FROM anon, authenticated;
ALTER TABLE merchant_analytics ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON merchant_analytics FROM anon, authenticated;
ALTER TABLE merchant_settings ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON merchant_settings FROM anon, authenticated;
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON notifications FROM anon, authenticated;
ALTER TABLE paypal_connections ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON paypal_connections FROM anon, authenticated;
ALTER TABLE products ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON products FROM anon, authenticated;
ALTER TABLE revenue_predictions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON revenue_predictions FROM anon, authenticated;
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
